445	    /** Every claim on the sheet, newest first. */
446	    @Transactional(readOnly = true)
447	    public List<Claim> list(String sheetId) {
448	        return claims.findBySheetIdOrderByIdDesc(sheetId);
449	    }
450	
451	    /** Add a claim for a person; a missing date takes the sheet's today, a missing note is empty. Refused
452	     *  when its date is inside a closed period. */
453	    @Transactional
454	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
455	        sheets.load(sheetId, user);
456	        LocalDate today = sheetStore.findLockedById(sheetId).orElseThrow().getToday();
457	        Person person = people.findByIdAndSheetId(personId, sheetId)
458	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
459	        refuseIfClosed(sheetId, date != null ? date : today);
460	        refuseIfRetired(person, date != null ? date : today);
461	        Rollup.Figures before = rollup.of(sheetId);
462	        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), date != null ? date : today, noteOf(note)));
463	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, added, added.getNumber()));
464	        rollup.recordChanges(sheetId, user, before);
465	        return added;
466	    }
467	
468	    /** Change a claim's amount, date and note; a missing date takes the sheet's today. Only a draft can be
469	     *  changed: to change an open claim, void it and add a new one. Refused when its date, as it is or as it
470	     *  would become, is inside a closed period. */
471	    @Transactional
472	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note) {
473	        sheets.load(sheetId, user);
474	        LocalDate today = sheetStore.findLockedById(sheetId).orElseThrow().getToday();
475	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
476	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
477	        if (claim.getStatus() != ClaimStatus.DRAFT) {
478	            throw new ResponseStatusException(HttpStatus.CONFLICT,
479	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
480	        }
481	        refuseIfClosed(sheetId, claim.getDate());
482	        refuseIfClosed(sheetId, date != null ? date : today);
483	        refuseIfRetired(people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(), date != null ? date : today);
484	        Rollup.Figures before = rollup.of(sheetId);
485	        claim.setAmount(scaled(amount));
486	        claim.setDate(date != null ? date : today);
487	        claim.setNote(noteOf(note));
488	        Claim edited = claims.saveAndFlush(claim);
489	        Person person = people.findByIdAndSheetId(edited.getPersonId(), sheetId).orElseThrow();
490	        audit.recordOnCommit(entry("CLAIM_EDITED", user, person, edited, edited.getNumber()));
491	        rollup.recordChanges(sheetId, user, before);
492	        return edited;
493	    }
494	
495	    /**
496	     * Move a claim to a new status; a move its current status does not allow is refused. Opening a
497	     * claim gives it the sheet's next number and records who opened it; voiding it keeps its number, which is
498	     * never given again; settling it fixes its due
499	     * at its person's grade's rate in force on its date, as rates are now, so later rate changes leave it as it is. The user
500	     * who opened a claim cannot settle it, and a clerk can settle it only when that due is at or below the sheet's
501	     * clerk limit (a claim with no due is within any limit); a steward settles anything. A claim dated inside a closed period cannot move. The sheet is locked
502	     * first, so moves on one sheet are made one at a time and no number is given twice.
503	     */
504	    @Transactional
505	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
506	        sheets.load(sheetId, user);
507	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
508	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
509	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
510	        refuseIfClosed(sheetId, claim.getDate());
511	        if (!claim.getStatus().canBecome(next)) {
512	            throw new ResponseStatusException(HttpStatus.CONFLICT,
513	                    "A " + claim.getStatus() + " claim cannot become " + next);
514	        }
515	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
516	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
517	        }
518	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
519	        BigDecimal due = Rate.inForceOn(rates.findBySheetIdAndGrade(sheetId, person.getGrade()), claim.getDate())
520	                .map(Rate::getRate).map(rate -> dueOn(claim.getAmount(), rate)).orElse(null);
521	        if (next == ClaimStatus.SETTLED) {
522	            refuseOverClerkLimit(sheet, user, due);
523	        }
524	        Rollup.Figures before = rollup.of(sheetId);
525	        Integer number = claim.getNumber();
526	        claim.setStatus(next);
527	        if (next == ClaimStatus.OPEN) {
528	            number = sheet.nextClaimNumber();
529	            claim.setNumber(number);
530	            claim.setOpenedBy(user);
531	        } else if (next == ClaimStatus.SETTLED) {
532	            claim.setSettledDue(due);
533	        }
534	        Claim changed = claims.saveAndFlush(claim);
535	        String event = switch (next) {
536	            case OPEN -> "CLAIM_OPENED";
537	            case SETTLED -> "CLAIM_SETTLED";
538	            case VOID -> "CLAIM_VOIDED";
539	            case DRAFT -> throw new IllegalStateException();
540	        };
541	        String line = entry(event, user, person, changed, number);
542	        if (next == ClaimStatus.SETTLED) {
543	            line += " due=" + (changed.getSettledDue() == null ? "n/a" : changed.getSettledDue().toPlainString());
544	        }
545	        audit.recordOnCommit(line);
546	        rollup.recordChanges(sheetId, user, before);
547	        return changed;
548	    }
549	
550	    /** Refuse a clerk settling a claim whose due is above the sheet's clerk limit; a steward settles anything,
551	     *  and a claim with no due is within any limit. */
552	    private void refuseOverClerkLimit(Sheet sheet, String user, BigDecimal due) {
553	        BigDecimal limit = sheet.getClerkLimit();
554	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
555	            return;
556	        }
557	        if (!Role.STEWARD.equals(roles.roleOf(sheet.getId(), user))) {
558	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
559	                    "A clerk cannot settle a claim whose due is above the clerk limit of " + limit.toPlainString());
560	        }
561	    }
562	
563	    /** Refuse a change to a claim dated inside a closed period of the sheet. */
564	    private void refuseIfClosed(String sheetId, LocalDate date) {
565	        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)) {
566	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period");
567	        }
568	    }
569	
570	    /** Refuse a claim dated after its person's retirement date. */
571	    private static void refuseIfRetired(Person person, LocalDate date) {
572	        if (person.refusesClaimOn(date)) {
573	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
574	                    "That claim is dated after " + person.getName() + " retired");
575	        }
576	    }
577	
578	    /** An audit line about a claim; one with a number (a void claim keeps the one it had) ends with it. */
579	    private static String entry(String event, String user, Person person, Claim claim, Integer number) {
580	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
581	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
582	                + (number == null ? "" : " number=" + number);
583	    }
584	
585	    /** The due on an amount at a rate (a percent): amount × rate / 100, rounded half to even to the cent. */
586	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal rate) {
587	        return amount.multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
588	    }
589	
590	    private static BigDecimal scaled(BigDecimal amount) {
591	        return amount.setScale(2, RoundingMode.UNNECESSARY);
592	    }
593	
594	    private static String noteOf(String note) {
595	        return note == null ? "" : note.trim();
596	    }
597	}
598	package net.officefloor.hq.app.rollup;
599	
600	import java.math.BigDecimal;
601	import java.time.LocalDate;
602	import java.util.LinkedHashMap;
603	import java.util.List;
604	import java.util.Map;
605	import java.util.Objects;
606	import net.officefloor.hq.app.Audit;
607	import net.officefloor.hq.app.claim.Claim;
608	import net.officefloor.hq.app.claim.ClaimRepository;
609	import net.officefloor.hq.app.claim.ClaimService;
610	import net.officefloor.hq.app.person.Person;
611	import net.officefloor.hq.app.person.PersonRepository;
612	import net.officefloor.hq.app.rate.Rate;
613	import net.officefloor.hq.app.rate.RateRepository;
614	import net.officefloor.hq.app.sheet.Sheet;
615	import net.officefloor.hq.app.sheet.SheetRepository;
616	import org.springframework.stereotype.Service;
617	
618	/**
619	 * The figures of a sheet as the screen shows them: each person's claimed and due-total, and the
620	 * sheet's claimed-total and due-total. A change takes the figures before it and, once made, records
621	 * a ROLLUP line for each person whose figures moved and a TOTALS line when the sheet's totals moved.
622	 */
623	@Service
624	public class Rollup {
625	
626	    /** A person's figures: claimed and due-total, each with two decimals; due-total is "n/a" when they have none. */
627	    public record PersonFigures(String name, String claimed, String dueTotal) {
628	    }
629	
630	    /** A sheet's figures: each person's, by id in the order they were added, and the sheet's totals. */
631	    public record Figures(Map<Long, PersonFigures> people, String claimedTotal, String dueTotal) {
632	    }
633	
634	    private static final String NOT_AVAILABLE = "n/a";
635	
636	    private final SheetRepository sheets;
637	    private final PersonRepository people;
638	    private final ClaimRepository claims;
639	    private final RateRepository rates;
640	    private final Audit audit;
641	
642	    public Rollup(SheetRepository sheets, PersonRepository people, ClaimRepository claims, RateRepository rates,
643	            Audit audit) {
644	        this.sheets = sheets;
645	        this.people = people;
646	        this.claims = claims;
647	        this.rates = rates;
648	        this.audit = audit;
649	    }
650	
651	    /** The sheet's figures as the store holds them now. */
652	    public Figures of(String sheetId) {
653	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
654	        List<Rate> sheetRates = rates.findBySheetId(sheetId);
655	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
656	        Map<Long, PersonFigures> byPerson = new LinkedHashMap<>();
657	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
658	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
659	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
660	            List<Rate> gradeRates = sheetRates.stream().filter(r -> r.getGrade().equals(person.getGrade())).toList();
661	            List<Claim> counting = sheetClaims.stream()
662	                    .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c.getStatus()))
663	                    .toList();
664	            BigDecimal claimed = counting.stream().map(Claim::getAmount)
665	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
666	            claimedTotal = claimedTotal.add(claimed);
667	            // As on screen: with no rate in force today and no fixed figure, the person has no due-total.
668	            boolean anyFixed = counting.stream().anyMatch(c -> c.getSettledDue() != null || c.getStatedDue() != null);
669	            String due = NOT_AVAILABLE;
670	            if (anyFixed || (today != null && Rate.inForceOn(gradeRates, today).isPresent())) {
671	                BigDecimal total = counting.stream().map(c -> dueOf(c, gradeRates))
672	                        .filter(Objects::nonNull)
673	                        .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
674	                dueTotal = dueTotal.add(total);
675	                due = total.toPlainString();
676	            }
677	            byPerson.put(person.getId(), new PersonFigures(person.getName(), claimed.toPlainString(), due));
678	        }
679	        return new Figures(byPerson, claimedTotal.toPlainString(), dueTotal.toPlainString());
680	    }
681	
682	    /** The due-total of the claims that count (a held person's OPEN ones do not) dated from {@code from} to {@code to} inclusive, as the
683	     *  screen shows a period's: each claim's due, none counting as 0. */
684	    public BigDecimal dueTotalBetween(String sheetId, LocalDate from, LocalDate to) {
685	        List<Rate> sheetRates = rates.findBySheetId(sheetId);
686	        Map<Long, Person> personOf = new LinkedHashMap<>();
687	        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> personOf.put(p.getId(), p));
688	        BigDecimal total = BigDecimal.ZERO.setScale(2);
689	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
690	            Person person = personOf.get(claim.getPersonId());
691	            if (person == null || !person.counts(claim.getStatus()) || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
692	                continue;
693	            }
694	            String grade = person.getGrade();
695	            BigDecimal due = dueOf(claim, sheetRates.stream().filter(r -> r.getGrade().equals(grade)).toList());
696	            if (due != null) {
697	                total = total.add(due);
698	            }
699	        }
700	        return total;
701	    }
702	
703	    /**
704	     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
705	     * for each person whose figures changed (one who did not exist before counting as changed), then a
706	     * TOTALS line if the sheet's totals changed. Nothing is recorded when no figure moved.
707	     */
708	    public void recordChanges(String sheetId, String user, Figures before) {
709	        Figures after = of(sheetId);
710	        after.people().forEach((id, figures) -> {
711	            PersonFigures was = before.people().get(id);
712	            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())) {
713	                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
714	                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal());
715	            }
716	        });
717	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())) {
718	            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
719	                    + " due-total=" + after.dueTotal());
720	        }
721	    }
722	
723	    /** A claim's due: its settled figure, else its stated one, else its amount at its grade's rate in force on its date. */
724	    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates) {
725	        if (claim.getSettledDue() != null) {
726	            return claim.getSettledDue();
727	        }
728	        if (claim.getStatedDue() != null) {
729	            return claim.getStatedDue();
730	        }
731	        return Rate.inForceOn(gradeRates, claim.getDate())
732	                .map(rate -> ClaimService.dueOn(claim.getAmount(), rate.getRate())).orElse(null);
733	    }
734	}
735	-- The sheet's clerk limit: a clerk can settle a claim only when its due is at or below it. NULL
736	-- means no limit.
737	ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(14, 2) CHECK (clerk_limit >= 0);
738	
739	-- The role the sheet's settings assign to a user name. A name with no row is a clerk.
740	CREATE TABLE sheet_role (
741	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
742	    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
743	    user_name VARCHAR(100) NOT NULL,
744	    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
745	    UNIQUE (sheet_id, user_name)
746	);
