import { Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { EMPTY, switchMap } from 'rxjs';
import { ROLES, RoleName, Roles } from '../../core/roles';
import { Sheets } from '../../core/sheet';

/** A clerk limit the form accepts: an amount of 0.00 or more with up to two decimals. */
const LIMIT_PATTERN = /^\d{1,12}(\.\d{1,2})?$/;

// The sheet's settings: its clerk limit, and the role assigned to each user name.
@Component({
  selector: 'app-settings',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="settings-heading">
      <h2 id="settings-heading">Settings</h2>
      <p>Clerk limit: <span data-testid="setting-clerk-limit-current">{{ sheets.current()?.clerkLimit ?? '' }}</span></p>

      <form [formGroup]="settingsForm" (ngSubmit)="saveSettings()" aria-label="Change the sheet's settings">
        <label for="setting-clerk-limit">Clerk limit (blank: no limit)</label>
        <input id="setting-clerk-limit" data-testid="setting-clerk-limit" formControlName="clerkLimit"
               inputmode="decimal" autocomplete="off" />
        <button type="submit" data-testid="settings-save" [disabled]="savingSettings()">Save settings</button>
        @if (settingsError(); as err) {
          <p role="alert" data-testid="settings-error">{{ err }}</p>
        }
      </form>

      <h3>Roles</h3>
      <p>A name with no role assigned is a clerk.</p>
      <ul aria-label="Roles assigned">
        @for (r of roles.all(); track r.user) {
          <li [attr.data-testid]="'role-row-' + r.user">
            {{ r.user }}: <span data-testid="role-value">{{ r.role }}</span>
          </li>
        }
      </ul>

      <form [formGroup]="roleForm" (ngSubmit)="saveRole()" aria-label="Assign a role">
        <label for="role-form-user">User name</label>
        <input id="role-form-user" data-testid="role-form-user" formControlName="user" autocomplete="off" />
        <label for="role-form-role">Role ({{ roleNames }})</label>
        <input id="role-form-role" data-testid="role-form-role" formControlName="role" autocomplete="off" list="role-names" />
        <datalist id="role-names">
          @for (r of roleChoices; track r) {
            <option [value]="r"></option>
          }
        </datalist>
        <button type="submit" data-testid="role-form-submit" [disabled]="savingRole()">Set role</button>
        @if (roleError(); as err) {
          <p role="alert" data-testid="role-form-error">{{ err }}</p>
        }
      </form>
    </section>
  `,
})
export class SettingsPanel {
  protected readonly sheets = inject(Sheets);
  protected readonly roles = inject(Roles);

  protected readonly roleChoices = ROLES;
  protected readonly roleNames = ROLES.join(' or ');
  protected readonly settingsError = signal<string | null>(null);
  protected readonly roleError = signal<string | null>(null);
  protected readonly savingSettings = signal(false);
  protected readonly savingRole = signal(false);

  protected readonly settingsForm = new FormGroup({
    clerkLimit: new FormControl('', { nonNullable: true }),
  });
  protected readonly roleForm = new FormGroup({
    user: new FormControl('', { nonNullable: true }),
    role: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // Each (re)load of a sheet re-reads its roles and settings from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.settingsError.set(null);
          this.roleError.set(null);
          this.settingsForm.reset({ clerkLimit: sheet?.clerkLimit ?? '' }, { emitEvent: false });
          return this.roles.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.roleError.set('Could not read the roles.') });
    // An error is removed as soon as its form is changed.
    this.settingsForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.settingsError.set(null));
    this.roleForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.roleError.set(null));
  }

  protected saveSettings(): void {
    // A second submit before the first has answered is ignored, so it stores one change.
    if (this.savingSettings()) return;
    this.settingsError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const limit = this.settingsForm.controls.clerkLimit.value.trim();
    if (limit !== '' && !LIMIT_PATTERN.test(limit)) {
      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
      return;
    }
    this.savingSettings.set(true);
    this.sheets.setSettings(sheet.id, limit === '' ? null : limit).subscribe({
      next: () => this.savingSettings.set(false),
      error: () => {
        this.savingSettings.set(false);
        this.settingsError.set('Could not save the settings.');
      },
    });
  }

  protected saveRole(): void {
    // A second submit before the first has answered is ignored, so it stores one record.
    if (this.savingRole()) return;
    this.roleError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const user = this.roleForm.controls.user.value.trim();
    const role = this.roleForm.controls.role.value.trim();
    if (!user) {
      this.roleError.set('Type the user name to assign a role to.');
      return;
    }
    if (!(ROLES as readonly string[]).includes(role)) {
      this.roleError.set(`Choose a role: ${this.roleNames}.`);
      return;
    }
    this.savingRole.set(true);
    this.roles.set(sheet.id, user, role as RoleName).subscribe({
      next: () => {
        this.savingRole.set(false);
        this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
      },
      error: () => {
        this.savingRole.set(false);
        this.roleError.set('Could not assign that role.');
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';
import { Grade } from './people';
import { Sheets } from './sheet';

export interface RateView {
  grade: Grade;
  /** The percent with exactly two decimals, e.g. "12.50". */
  rate: string;
  /** The day it takes effect (yyyy-mm-dd); null when it applies from the beginning of time. */
  from: string | null;
}

/** The rate among a grade's rates (in the order they take effect) in force on a date (yyyy-mm-dd):
 *  the one with the latest from-date on or before it; undefined when the date is before them all. */
export function rateOn(gradeRates: readonly RateView[], date: string): string | undefined {
  let inForce: string | undefined;
  for (const r of gradeRates) if (r.from === null || r.from <= date) inForce = r.rate;
  return inForce;
}

/** Rates in the order they take effect: the one with no from-date first, then by from-date. */
function byFrom(a: RateView, b: RateView): number {
  return a.from === b.from ? 0 : a.from === null ? -1 : b.from === null ? 1 : a.from < b.from ? -1 : 1;
}

/** A rate the form accepts: a percent of 0.00 or more, up to 999.99, with up to two decimals. */
export const RATE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** What is shown in place of a due when its grade has no rate. */
export const NOT_AVAILABLE = 'n/a';

/** The due on an amount (in whole cents) at a rate (a percent, e.g. "12.50"), in whole cents:
 *  amount × rate / 100, rounded half to even to the cent. Exact, whatever the size of the amount. */
export function dueCents(amountCents: number, rate: string): number {
  const [whole, frac = ''] = rate.split('.');
  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
  const product = BigInt(amountCents) * basisPoints;
  const quotient = product / 10000n;
  const remainder = product % 10000n;
  const roundUp = remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n);
  return Number(roundUp ? quotient + 1n : quotient);
}

/** A claim's due in whole cents: the figure fixed when it was settled, else the figure its person's
 *  last statement bound it to, else its amount at its grade's rate in force on its date; null when it has none. */
export function claimDueCents(
  c: { amount: string; date: string; settledDue: string | null; statedDue: string | null },
  gradeRates: readonly RateView[],
): number | null {
  if (c.settledDue !== null) return amountCents(c.settledDue);
  if (c.statedDue !== null) return amountCents(c.statedDue);
  const rate = rateOn(gradeRates, c.date);
  return rate === undefined ? null : dueCents(amountCents(c.amount), rate);
}

/** An amount ("12.3", "4") in whole cents. */
function amountCents(amount: string): number {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0').slice(0, 2));
}

// The rates set for each grade on the active sheet, by from-date; a grade with none has no rate.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly sheets = inject(Sheets);
  private readonly list = signal<RateView[]>([]);
  /** The active sheet's rates of each grade, in the order they take effect. */
  readonly ratesByGrade = computed(() => {
    const byGrade = new Map<Grade, RateView[]>();
    for (const r of [...this.list()].sort(byFrom)) byGrade.set(r.grade, [...(byGrade.get(r.grade) ?? []), r]);
    return byGrade;
  });
  /** The rate of each grade in force on the active sheet's today; a grade with none is missing. */
  readonly byGrade = computed(() => {
    const today = this.sheets.current()?.today ?? '';
    const current = new Map<Grade, string>();
    for (const [grade, rates] of this.ratesByGrade()) {
      const rate = rateOn(rates, today);
      if (rate !== undefined) current.set(grade, rate);
    }
    return current;
  });

  /** Re-read a sheet's rates from the store; null clears them. */
  load(sheetId: string | null): Observable<RateView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<RateView[]>(this.base(sheetId)).pipe(tap((rates) => this.list.set(rates)));
  }

  /** Set a grade's rate from a date (null: from the beginning of time), replacing the one it had from that date. */
  set(sheetId: string, grade: Grade, rate: string, from: string | null): Observable<RateView> {
    return this.http
      .put<RateView>(`${this.base(sheetId)}/${grade}`, { rate, from })
      .pipe(
        tap((saved) =>
          this.list.update((list) => [...list.filter((r) => r.grade !== saved.grade || r.from !== saved.from), saved]),
        ),
      );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

export interface SheetView {
  id: string;
  /** The sheet's today (yyyy-mm-dd): every date-dependent decision and default uses it, never the clock. */
  today: string;
  /** A clerk can settle a claim only when its due is at or below this (two decimals); null: no limit. */
  clerkLimit: string | null;
}

// The active sheet. Everything else in the app is kept per sheet; loading an id re-reads it from
// the store, and an id never loaded before starts an empty sheet.
@Injectable({ providedIn: 'root' })
export class Sheets {
  private readonly http = inject(HttpClient);
  private readonly active = signal<SheetView | null>(null);
  readonly current = this.active.asReadonly();
  /** The sheet as last (re)loaded: set on each load only, so changing its today re-reads nothing. */
  private readonly lastLoad = signal<SheetView | null>(null);
  readonly loaded = this.lastLoad.asReadonly();

  load(id: string): Observable<SheetView> {
    return this.http
      .post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null)
      .pipe(
        tap((s) => {
          this.active.set(s);
          this.lastLoad.set(s);
        }),
      );
  }

  /** Change the active sheet's today. */
  setToday(id: string, today: string): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Change the active sheet's settings; a null clerk limit means no limit. */
  setSettings(id: string, clerkLimit: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings`, { clerkLimit })
      .pipe(tap((s) => this.active.set(s)));
  }
}
